CREATE proc [dbo].[uspGetRunningTables] @TiltId as int, @Waiter as nvarchar(50), @ShiftNo as nvarchar(50) as  select order_key as 'Key',table_no as 'Table',Od as 'Ord #',order_time as [Time],waiter_name as 'Server', service_status as 'S Status',account_status as 'A Status',IsBill,TiltId,KOT  from Dine_In_Order  where  Account_status = 'Not Paid' and service_status <> 'Close'  and service_status <> 'Void'  and is_delete = '0' and order_type = 'DINE IN'  and TiltId = @TiltId and waiter_name = @Waiter and z_number = @ShiftNo order by cast(table_no as int) asc  